import { AbilityName, CardName } from '@/lib/types';

/** Public paths of one card's or ability's art. Generated by scripts/art/generate-card-art.py. */
export interface CardArt {
  /** 128x128 transparent icon, for lists, badges and buttons. */
  icon: string;
  /** 400x600 framed portrait card with no text; the game draws the name and description. */
  card: string;
}

const ART_DIR = '/sprites/cards';

function artFor(slug: string): CardArt {
  return { icon: `${ART_DIR}/${slug}-icon.webp`, card: `${ART_DIR}/${slug}-card.webp` };
}

/** Typed by CardName, so a new card fails typecheck until it has art. */
export const CARD_ART: Record<CardName, CardArt> = {
  [CardName.ExtraMove]: artFor('extra-move'),
  [CardName.StealResource]: artFor('steal-resource'),
  [CardName.Sabotage]: artFor('sabotage'),
  [CardName.Reinforce]: artFor('reinforce'),
  [CardName.Scout]: artFor('scout'),
  [CardName.Overcome]: artFor('overcome'),
  [CardName.Wealthy]: artFor('wealthy'),
  [CardName.Productive]: artFor('productive'),
  [CardName.Efficient]: artFor('efficient'),
  [CardName.MasterBuilder]: artFor('master-builder'),
  [CardName.WarChief]: artFor('war-chief'),
  [CardName.DecideDiceRoll]: artFor('decide-dice-roll'),
  [CardName.Teleport]: artFor('teleport'),
};

export const ABILITY_ART: Record<AbilityName, CardArt> = {
  [AbilityName.Explorer]: artFor('explorer'),
  [AbilityName.Collector]: artFor('collector'),
};
